namespace PsychologyApp.Application.Articles;

public static partial class ArticleContent
{
    private static readonly Article[] AdditionalArticlesEn =
    [
        MiniArticle(ArticleIds.CallNerves, "Nerves before a call", "Make the first call shorter and clearer", "Do not rehearse the whole conversation. Write down one goal and an opening sentence. During the call, you can use your note, ask someone to repeat something, or pause. Count making the call as success, not speaking perfectly."),
        MiniArticle(ArticleIds.WaitingForReply, "Waiting for a reply", "Silence in a chat does not explain itself", "Write down three possible reasons for the silence, including a neutral one. Choose when you will check again. If the question is urgent, decide whom to contact and when instead of refreshing the screen."),
        MiniArticle(ArticleIds.AfterSocialEvent, "After a social event: stop replaying every line", "How to interrupt the mental replay", "Name one moment that went fine and one conclusion you cannot draw yet. Do not search for a perfect line after the fact. Return to what you are doing; you can revisit an important conversation later."),
        MiniArticle(ArticleIds.FearOfMistakes, "A mistake is not a verdict", "Set a clear standard for good enough", "Before starting, decide what result will be sufficient and check one important requirement. If a mistake happens, find out its real impact and the next repairable step. One slip does not define you as a whole."),
        MiniArticle(ArticleIds.ChangeAnxiety, "When change feels worrying", "Separate facts from what is still unknown", "Make two columns: what you know and what you could find out. Choose one question and a time to return to it. The rest does not need an answer yet; uncertainty is not the same as a bad outcome."),
        MiniArticle(ArticleIds.WorryBeforeTask, "Before a difficult task", "Start without demanding complete confidence", "Decide what you need for a safe start: materials, ten minutes, or clarification. Begin with just that part. Then choose whether to continue. You do not have to wait for anxiety to disappear or for a perfect plan."),
        MiniArticle(ArticleIds.AvoidedFirstStep, "Take only the first step", "Starting can take two minutes", "Make the beginning small: open the file, write a heading, or take out the materials. You are allowed to stop afterward. The aim is to make starting easier, not to trick yourself out of taking a break."),
        MiniArticle(ArticleIds.CheckingLoop, "Check, then stop", "Set a limit before you check", "Decide what you are checking and how many times. After the last check, mark it done and switch tasks. If anxiety asks you to repeat it, name that as anxiety's request, not new evidence."),
        MiniArticle(ArticleIds.PublicPlaceAnxiety, "Anxiety in a public place", "Find an anchor and keep your choices", "Feel the support under your feet and name a few things around you. Choose a place where you can stand calmly. You can leave or ask for help if you are unsafe; an exercise should never keep you there."),
        MiniArticle(ArticleIds.MorningWorry, "A morning without a list of worries", "You do not need to solve the whole week before breakfast", "Write down the worries and mark one real need for today. Schedule the rest or leave them until you have new information. Begin with one step, not an attempt to anticipate everything."),
        MiniArticle(ArticleIds.SensoryOverload, "When there is too much noise and activity", "Reduce the load on your attention", "If possible, remove one source of noise, dim the screen, or move somewhere quieter. Choose one anchor for your attention. A pause does not require you to return to your previous pace right away."),
        MiniArticle(ArticleIds.EveningTension, "End the day gently", "Move unfinished tasks to tomorrow", "Take a few minutes to write what is done, what can wait, and where you will begin tomorrow. If your routine fell apart, choose one repeatable cue for bedtime instead of a strict ritual that is easy to break."),
        MiniArticle(ArticleIds.AnxietyComedown, "After a surge of anxiety", "Recover first; reflect later", "Make sure you are safe and give yourself time to return to your usual pace. Choose a simple, familiar activity if that helps. Later, note what helped and what you might want to discuss with a professional."),
        MiniArticle(ArticleIds.SafePractice, "A practice is not a test", "Adapt an exercise to suit you", "You can shorten it, keep your eyes open, skip a step, or stop. If it feels uncomfortable, return to your natural breathing and choose another anchor. You do not have to endure discomfort to follow instructions."),

        MiniArticle(ArticleIds.ThoughtLabel, "Give a thought a name", "Notice a thought without arguing with it", "Try saying, “I am noticing the thought that…” This does not prove the thought wrong; it helps you see it as a thought. Then ask which small action fits your task or values right now."),
        MiniArticle(ArticleIds.MindReading, "Do not guess what others think", "Separate what you saw from what you inferred", "Write down what the person literally said or did, then what you added as an interpretation. If the answer matters, ask calmly and directly. If it does not, leave it open instead of treating a guess as fact."),
        MiniArticle(ArticleIds.WorstVsLikely, "The worst outcome is not the most likely", "Make room for more than one possibility", "Write down the worst, best, and most plausible outcomes. Prepare for the plausible one; make one reasonable safety plan for the worst if it is genuinely needed. Do not spend your energy planning every imagined scenario in detail."),
        MiniArticle(ArticleIds.EvidenceAndUnknown, "What I know and what I do not", "Do not fill a gap with an anxious guess", "Make two columns: “I know” and “I do not know yet.” For the unknown, choose how to get information or when to review it. If you cannot find out now, let the question stay open until facts appear."),
        MiniArticle(ArticleIds.NegativityFilter, "Notice more than what went wrong", "Add one more fact to the picture", "After a hard event, the mind can focus on mistakes and miss ordinary or good moments. Name one fact that does not fit the negative version. You do not have to insist that everything is fine; just see the whole picture."),
        MiniArticle(ArticleIds.ConversationReplay, "Stop replaying the conversation endlessly", "Decide whether there is a next step", "Ask whether there is a specific problem you can repair. If so, write down one short next step. If not, call the replay a replay and return to what you can see, hear, or do now."),
        MiniArticle(ArticleIds.DecisionFatigue, "Simplify a small choice", "Decide in advance what is good enough", "For recurring small choices, use a simple rule: a budget, a time limit, or one quality criterion. Apply it without comparing every option forever. Set aside time and gather facts separately for important decisions."),
        MiniArticle(ArticleIds.GoodEnough, "Good enough is still a result", "Limit unnecessary polishing", "Name two requirements the result needs to meet and a time to stop. When both are met, save or send it. Make more edits only to fix a concrete issue, not to chase impossible perfection."),
        MiniArticle(ArticleIds.ControlInfluence, "What I can influence and what I cannot", "Focus on an action that is available to you", "Draw two circles: what depends on you and what does not. Choose one step inside the first; for the outer circle, consider a boundary, support, or accepting uncertainty. This does not erase real unfairness or constraints."),
        MiniArticle(ArticleIds.SelfTalkReset, "Change the tone of your self-talk", "Be respectful and specific with yourself", "Replace “I ruined everything again” with an action: “I missed the deadline; now I will ask what can be fixed.” This does not excuse the mistake. It helps you find a next step without insulting yourself."),
        MiniArticle(ArticleIds.WorryAboutWorry, "Worrying about being worried", "Do not demand that you calm down at once", "When you think, “I should not feel this way,” call it a second wave of worry. Let the first reaction be there and return to the nearest task. If anxiety often gets in the way of life, consider talking to a professional."),
        MiniArticle(ArticleIds.CompareHighlightReel, "Do not compare your life with someone else's showcase", "A feed shows selected moments, not a whole life", "Remember that a post is a fragment, not someone's entire day. If comparison hurts your mood, pause the feed and choose your own reference point: what matters to you, not what looks impressive."),
        MiniArticle(ArticleIds.IntrusiveThoughts, "An unwanted thought is not an intention", "Look at actions and context, not the thought alone", "A distressing thought can be frightening because it conflicts with what you want. You do not need to test yourself over and over. Notice it and return to your chosen task; if it seriously interferes, seek professional support."),
        MiniArticle(ArticleIds.OneThingAtATime, "One task at a time", "Reduce the cost of switching", "Write down what needs attention and choose one task for a short stretch. Close extra tabs or notifications if you can. The other tasks are not gone; they are simply waiting their turn on the list."),

        MiniArticle(ArticleIds.MoodMovement, "A little movement when energy is low", "Action does not have to wait for a better mood", "Choose an accessible movement for a couple of minutes: stretch, walk around the room, or look outside. Notice how you feel afterward. This is an experiment, not a demand to exercise or to feel better."),
        MiniArticle(ArticleIds.PleasureMastery, "Enjoyment and a sense of completion", "Notice different kinds of supportive activity", "You might plan one pleasant activity and one small task that could bring a sense of completion. They can be the same thing. If it does not happen, that is information about your load, not a reason to blame yourself."),
        MiniArticle(ArticleIds.EnergyBudget, "Budget energy as well as time", "Leave room to recover", "Look at your day and mark which tasks take the most energy. If possible, put a short break or an easier task between them. A plan with some room is often more practical than a schedule without a pause."),
        MiniArticle(ArticleIds.RestBreak, "Take a break without guilt", "Rest can help with the next choice", "Choose a short break and decide what feels restful for you: quiet, water, stretching, or looking into the distance. Do not turn the pause into another assignment. If your workload leaves no room to rest, discipline is not the only issue."),
        MiniArticle(ArticleIds.StartFriction, "Remove one obstacle before you start", "Prepare the beginning in advance", "Notice what usually gets in the way: finding a file, too many steps, or an unclear task. Prepare only the next piece: open the document, lay out materials, or write the first question. You do not have to organize everything."),
        MiniArticle(ArticleIds.TransitionRitual, "Switch between tasks", "A short pause can make the next step clearer", "Before a new task, pause for a minute: close the previous file, note what is unfinished, and name what comes next. This is not a required ritual or a way to work more at any cost, just a clear transition."),
        MiniArticle(ArticleIds.TaskActivation, "When starting feels hard", "Let action come before motivation", "Choose a visible action that takes less than five minutes; use a timer only if it helps. When it ends, decide whether to continue. Motivation may arrive after starting, but you do not have to push through."),
        MiniArticle(ArticleIds.GentleRoutine, "A flexible routine instead of a perfect one", "Keep one steady point in your day", "Choose a small repeatable cue, such as planning after breakfast. If the time changes, keep the sequence rather than the exact minute. Missing a day does not prevent you from returning to the habit."),
        MiniArticle(ArticleIds.WakeAtNight, "If you wake during the night", "Keep things calm and avoid checking the clock", "Try not to judge the night minute by minute. If lying there feels unpleasant, you could briefly do a quiet activity in dim light and return when sleepy. If sleep problems persist, discuss them with a clinician."),
        MiniArticle(ArticleIds.SmallDayPlan, "A day plan with some breathing room", "Choose the main thing and leave room for surprises", "Write down one important task, one small task, and a pause. Treat the rest as optional if time and energy allow. You can change the plan; flexibility does not mean you let yourself down."),
        MiniArticle(ArticleIds.AskForHelpTask, "Ask for help with one specific part", "A clear request leaves less room for guessing", "Instead of “help me,” name an action and a time: “Could you review this paragraph today?” Add what a useful result would look like. It is easier to answer, and easier for you to see whether the help fits."),
        MiniArticle(ArticleIds.MeaningfulActivity, "An activity that matters to you", "Connect a small step to one of your values", "Ask what matters in this situation: care, curiosity, reliability, or rest. Choose one small action in that direction. It does not need to change the whole situation at once to be meaningful."),
        MiniArticle(ArticleIds.FlexibleGoals, "Change the plan without giving up the goal", "Match the step to today's capacity", "If the original plan is too much, reduce the amount or change the method. Keep the direction, not necessarily the form: ten minutes instead of an hour, or a draft instead of a perfect result. A goal can be flexible, not a punishment."),
        MiniArticle(ArticleIds.CelebrateCompletion, "Notice what you have done", "The mind often jumps straight to the next task", "When you finish, briefly name what you did and what effort it took. You do not need a reward; noticing the fact is enough. It helps you see more than the unchecked items."),

        MiniArticle(ArticleIds.NameEmotion, "Name the feeling more precisely", "A word can help you choose a response", "Instead of “I feel bad,” try a more specific word: tense, disappointed, afraid, or tired. You can be unsure; this is not a test. Then ask what you need now: safety, a pause, clarity, or connection."),
        MiniArticle(ArticleIds.MixedFeelings, "Two different feelings can be true at once", "Mixed feelings do not make you inconsistent", "You can feel excited about a change and miss what came before. Name both sides without forcing a choice. Ask which one needs attention now and offer it one small act of care."),
        MiniArticle(ArticleIds.AngerPause, "Pause before answering in anger", "Safety first, words second", "If a conversation is escalating, suggest a pause and say when you can return. Move somewhere safe and give yourself time. Do not use a pause to threaten; if there is a risk of violence, seek a safer place and help."),
        MiniArticle(ArticleIds.ShameKindness, "Meet shame without humiliating yourself", "You can repair a mistake without punishing yourself", "Tell yourself, “I feel ashamed right now, but this feeling does not describe all of me.” Separate the action from your identity: what happened, and can anything be repaired? Choose the response you would offer someone close to you."),
        MiniArticle(ArticleIds.GuiltRepair, "Guilt: repair something or let it go", "Separate responsibility from endless self-blame", "If you caused harm, consider a specific repair and a respectful apology. If no real boundary was crossed, guilt may be a feeling rather than proof. In either case, punishing yourself endlessly does not help the person who was hurt."),
        MiniArticle(ArticleIds.EnvyInformation, "Envy can point to something you want", "Turn comparison into a direction of your own", "Ask what you envy: freedom, recognition, closeness, or a skill? That does not make you a bad person. Choose a small step toward your need without copying someone else's life or dismissing your own path."),
        MiniArticle(ArticleIds.AllowSadness, "Sadness does not have to disappear right away", "Make room for the feeling and choose support", "Name the loss or disappointment without rushing yourself to cheer up. Consider what would be kind now: time alone, a message to someone close, or one necessary small task. If it keeps disrupting daily life, seek support."),
        MiniArticle(ArticleIds.Numbness, "When it is hard to feel anything", "Do not force yourself to open up at once", "Numbness can be one way the mind responds to overload, but it does not explain the cause by itself. Start with something neutral: where you are, what you see, and what you want in the next ten minutes. If it worries you or persists, talk to a professional."),
        MiniArticle(ArticleIds.EmotionWave, "A feeling can change, even if not right away", "Notice it without using a stopwatch", "Rate the feeling from zero to ten and name it in one word. You can check again later without demanding a lower number. The aim is to notice movement and have choices, not to time how quickly you calm down."),
        MiniArticle(ArticleIds.BodyNoticingChoice, "Notice your body at a comfortable pace", "You can choose an outside anchor instead", "If noticing body sensations feels unpleasant, do not force it. Look at a steady object, feel the chair supporting you, or name sounds around you. Body awareness is an option, not a requirement for self-help."),
        MiniArticle(ArticleIds.PauseBeforeReact, "Pause between an impulse and an action", "Choose a response you are less likely to regret", "If you want to send a message right away, wait a few minutes if it is safe to do so. Name the message's purpose and keep only the necessary words. If delay would cause harm, act; the pause should help, not get in the way."),
        MiniArticle(ArticleIds.EmotionalBoundary, "Someone else's feelings are not yours to fix", "You can care and still keep your boundaries", "You can listen without agreeing to everything or promising to solve the problem. Ask whether the person wants support or advice, and say what you can offer. Caring does not require giving up your own needs."),
        MiniArticle(ArticleIds.FeelingNotAction, "A feeling does not require an action", "There is a choice between emotion and behavior", "You can be angry without insulting someone, afraid and still ask for a pause, or jealous without checking someone's messages. Name the impulse, then choose an action that considers your feelings and other people's safety."),
        MiniArticle(ArticleIds.AfterCrying, "After crying", "Take care of the next minute", "You might wash your face or sit quietly, breathe normally, ask for water, or contact someone close. You do not have to explain the tears right away. If you are in danger or cannot stay safe, seek urgent help."),

        MiniArticle(ArticleIds.SpecificRequest, "Ask for something specific", "A clear request leaves room for an answer", "Try a simple structure: what happened, what you need, and by when. For example: “I cannot prepare the materials in time; could you take this part by Friday?” The other person can say no, and you can look for another option."),
        MiniArticle(ArticleIds.ListenReflect, "Understand first, then respond", "A brief check can lower tension", "Reflect what you heard in your own words and ask if you got it right. Do not add advice unless it was requested. Even if you disagree, you can show that you understood the message."),
        MiniArticle(ArticleIds.BoundarySentence, "A sentence for setting a boundary", "A short answer is often clearer than a long defense", "Try: “I cannot take this on now” or “That tone does not work for me; I can continue when we can speak calmly.” Adapt the words to your situation and safety. A boundary says what you will do, not what the other person must do."),
        MiniArticle(ArticleIds.NoWithoutEssay, "You can say no without a long explanation", "Choose a polite and clear phrase", "Try “Thanks, but I cannot” or “That does not work for me.” Offer an alternative only if you want to. In an unsafe situation, a direct refusal may not be the best option; choose what protects you."),
        MiniArticle(ArticleIds.DifficultTalkOpening, "Start a difficult conversation with a goal", "Talk about one event and one request", "Choose a calm moment, name a specific situation, and say what you hope to change. For example: “When plans change without warning, I struggle; can we tell each other sooner?” Do not start if it is unsafe now."),
        MiniArticle(ArticleIds.RepairAfterConflict, "Return to a conversation after an argument", "Take one small step toward clarity", "When both of you are ready, name your part and ask how the other person saw it. You do not have to resolve every disagreement at once. If the conversation becomes unsafe again, stop and seek support."),
        MiniArticle(ArticleIds.ApologyResponsibility, "Apologize without giving up your boundaries", "Name the action and what you will change", "A useful apology is specific: “I interrupted you; next time I will listen.” Do not add “but you…” in the same sentence. Owning your mistake does not mean agreeing with every accusation or giving up your safety."),
        MiniArticle(ArticleIds.FeedbackAsInformation, "Separate feedback from your worth", "Clarify what you can use", "Find the specific action you can change, and ask for an example if it is unclear. One result is not a judgment of your whole identity. Insults do not become helpful feedback just because they are called criticism."),
        MiniArticle(ArticleIds.ReceiveNo, "When someone says no", "A refusal of one request is not always a rejection of you", "Separate the answer to a specific request from what you conclude about yourself. If appropriate, ask whether there is another time or option. You can feel disappointed and still look for support elsewhere."),
        MiniArticle(ArticleIds.CheckAssumption, "Check a guess with a question", "Clarify the meaning before building a story", "If a message is ambiguous, ask neutrally: “Did I understand correctly that…?” This is more useful than replying to an assumed subtext. If you cannot ask, separate the fact from the guess and wait before concluding."),
        MiniArticle(ArticleIds.AskSupport, "Asking for support is a skill", "Say what would help", "You can ask someone to listen, walk beside you, or help with one task. Say whether you want ideas or just company. If they cannot help, that does not prove your needs are too much."),
        MiniArticle(ArticleIds.SupportWithoutFixing, "Be there without fixing everything", "Ask what kind of support is needed", "Try: “Would you like me to listen, stay with you, or help think through a next step?” Do not promise what you cannot do. Support respects the other person's choices and your own boundaries."),
        MiniArticle(ArticleIds.ConflictNotFailure, "Disagreement does not always mean a relationship is over", "Notice how you treat each other", "What matters is not only the disagreement, but also respect, the ability to pause, and willingness to discuss impact. You do not have to accept threats or violence to “save the relationship”; safety comes first."),
        MiniArticle(ArticleIds.MakeExpectationsClear, "State expectations in advance", "Do not wait for someone to guess", "Before doing something together, clarify timing, roles, and what counts as finished. Check that you understood the agreement in the same way. Clarity cannot guarantee agreement, but it can reveal a mismatch earlier."),
        MiniArticle(ArticleIds.DigitalBoundaries, "Boundaries in messaging", "Notifications do not have to run your day", "Choose when to reply and turn off nonessential alerts if that suits you. You can tell people close to you when you are usually available. Keep a clear separate way to reach you for urgent or unsafe situations."),
        MiniArticle(ArticleIds.FamilyPressure, "When family members pressure you with advice", "Thank them and say you will decide", "Try: “I hear that you are worried. I will think about it and decide.” If the conversation continues, repeat the same line or change the subject. Use this only if it does not increase risk for you."),
        MiniArticle(ArticleIds.FriendshipInvitation, "Invite someone without making a big plan", "A small invitation is easier to accept or decline", "Be specific and low-pressure: “Would you like to take a walk after work on Thursday?” Add that another time or a no is okay. Their answer reflects their availability now, not your worth."),
        MiniArticle(ArticleIds.SmallConnection, "A small connection still counts", "You do not have to begin with a deep conversation", "If you feel lonely, choose an easy way to be around people: a short message, a familiar place, or a neutral conversation. Stop when you have had enough. The aim is to try connection, not force yourself to become social at once."),

        MiniArticle(ArticleIds.OrientNow, "Check where you are now", "A gentle way to orient to the present", "Look around and name the place, date or time of day, a few objects, and what is happening now. Keep your eyes open and go at a comfortable pace. If this increases anxiety, switch to a neutral object outside you or ask for support."),
        MiniArticle(ArticleIds.GroundingChoice, "Choose grounding that suits you", "Not everyone is comfortable focusing on the body", "You can name colors, describe an object, feel the chair, or listen to a steady sound. Choose one thing that feels manageable now. If it makes you feel worse, stop and try something else."),
        MiniArticle(ArticleIds.AfterNightmare, "After a distressing dream", "Remind yourself that the dream has ended", "Turn on a gentle light, look around, and name a few signs that you are in your room now. You do not need to remember the dream in detail. If nightmares recur or disrupt sleep, discuss them with a healthcare professional."),
        MiniArticle(ArticleIds.AnniversaryReaction, "Difficult dates and anniversaries", "A reaction can come before or after the date", "If a date reminds you of a difficult event, leave fewer tasks and choose support in advance. You can mark the day in your own way or not at all. Strong feelings do not mean you are back at the beginning."),
        MiniArticle(ArticleIds.PaceRecovery, "Recover at your own pace", "Do not turn self-care into a marathon", "Choose one manageable practice and decide how long you want to spend on it. It is okay to stop or change methods. Notice not only your mood, but whether you feel more comfortable or safe."),
        MiniArticle(ArticleIds.SafetyFirst, "Safety matters more than an exercise", "Self-help does not require staying in danger", "If there is a threat nearby, first try to get somewhere safer and contact someone who can help. Breathing and grounding do not replace protection, medical care, or emergency services."),
        MiniArticle(ArticleIds.ChooseTrustedPerson, "Choose someone you can ask for support", "Think of a person you can contact simply", "Name one person who usually respects your boundaries. Prepare a short phrase: “I am having a hard time; could you stay in touch?” If no one is available, contact a professional or a local support service."),
        MiniArticle(ArticleIds.AfterStressRecovery, "After a stressful event", "Give yourself time to return to ordinary tasks", "After a hard day, choose one basic and one quiet activity: eat, change clothes, sit in silence, or message someone close. Do not demand that you explain everything or return to your previous productivity immediately."),
        MiniArticle(ArticleIds.FlashbackGrounding, "When the past feels close again", "Orient to the present and keep your choices", "Look around and name where you are and today's date if helpful. Choose a visible object or contact someone nearby. Do not force yourself to close your eyes, breathe deeply, or tell details; seek real help if you are in danger."),
        MiniArticle(ArticleIds.RecoveryNotLinear, "Recovery is not a straight line", "A difficult day does not erase your progress", "Compare yourself not with a perfect upward line, but with what helps you get through today. Strong feelings can return after a good stretch. If things worsen or become hard to manage, you can seek support again."),

        MiniArticle(ArticleIds.BreathIsOptional, "Breathing practice is optional", "Do not force yourself to change your breathing", "If focusing on breath feels unpleasant, let it stay natural and choose an outside anchor: a color, sound, or object. Breathing exercises do not suit everyone and do not replace care for significant shortness of breath or new symptoms."),
        MiniArticle(ArticleIds.GroundingCanChange, "When grounding does not help", "Switch methods or stop", "An exercise does not have to work every time. Try a simpler outside anchor, ask someone nearby to describe the room, or end the practice. A difficult attempt does not mean you did it wrong."),
        MiniArticle(ArticleIds.MovementAnchor, "Use movement as an anchor", "A small movement can restore a sense of choice", "If it is comfortable and safe, slowly open and close your hands or shift your weight. You could also watch an object move. Do not push through pain; choose a still object if that works better."),
        MiniArticle(ArticleIds.SensesAnchor, "An anchor through the senses", "Choose one neutral signal around you", "Name a color, the temperature of the air, or a steady sound that does not bother you. You do not need to find five things or close your eyes. One neutral signal may be enough; choose another if it feels unpleasant."),
        MiniArticle(ArticleIds.EarlyStressSigns, "Notice early signs of overload", "Noticing early gives you more options", "Think about what changes first for you: speech pace, tension, attention, or wanting to cancel everything. Write down that sign and one gentle response: pause, clarify the task, or ask for help. This is observation, not diagnosis."),
        MiniArticle(ArticleIds.RelaxWithoutForce, "Relax without effort", "You do not have to become completely calm", "Choose an action that takes little concentration: lower your shoulders, get more comfortable, or loosen your hands. Let your breath be natural. A little comfort is enough; do not force your body to relax fully."),
        MiniArticle(ArticleIds.BasicCareWithoutRules, "Basic care without strict rules", "Choose what you need right now", "Ask yourself what would help in the next hour: water, food, warmth, quiet, movement, or contact. Choose only what is available. If it is not possible, do not blame yourself; you may need help or conditions you do not have."),
        MiniArticle(ArticleIds.NewSymptomsCare, "New or unusual symptoms", "Do not diagnose yourself from an article", "If physical symptoms are new, severe, or changing quickly, contact a healthcare professional. For emergency warning signs, call local emergency services. A self-help exercise should not delay medical assessment."),
        MiniArticle(ArticleIds.FindTherapist, "How to look for a professional", "Look for a good fit, not a perfect description", "Ask about training, experience with your concern, format, cost, and confidentiality. At the first meeting, ask how the work is structured and how you will know whether it helps. You can seek a different professional if the fit is not right."),
        MiniArticle(ArticleIds.FirstAppointment, "Your first appointment", "You do not need to prepare a perfect story", "Write down a couple of topics that matter most and questions about the sessions. You can say “I find it hard to explain” and start with an example from last week. You can ask for a pause or clarify what stays confidential."),
        MiniArticle(ArticleIds.DescribeSymptoms, "How to describe what is happening", "A real example is more useful than perfect terms", "Say when it started, how often it happens, and what changes in daily life. If speaking is hard, bring a note or show it to the professional. You do not need to guess a diagnosis before asking for help."),
        MiniArticle(ArticleIds.SelfHelpLimits, "When self-help is not enough", "Professional support is a valid next step", "If things keep disrupting sleep, work, study, or self-care, get worse, or exercises do not help, contact a healthcare professional or psychologist. You do not need to prove that you tried hard enough alone."),

        MiniArticle(ArticleIds.ScreeningNotDiagnosis, "A questionnaire is not a diagnosis", "A result can start a conversation, not label you", "Answers reflect how you felt over a particular period and can depend on circumstances. Share a result with a professional if it worries you. Do not change treatment or make major decisions based only on a score."),
        MiniArticle(ArticleIds.SupportPlan, "Make a short support plan", "Write down signs, steps, and contacts", "Note how you recognize things getting harder, what tends to help, and whom you can tell. Add professional contacts and local emergency services. A plan does not replace help; it points to whom to contact when thinking is hard."),
        MiniArticle(ArticleIds.CrisisSteps, "If you are not safe right now", "Connect with real-time help", "Move somewhere safer if possible and contact local emergency services or someone you trust. Say briefly what is happening and where you are. Do not stay alone if there is immediate danger."),
        MiniArticle(ArticleIds.MedicationWithClinician, "Medication questions belong with a professional", "Do not change a prescription on your own", "If you have concerns about medication, write down its name, your question, and any unwanted effect, then discuss it with the prescriber or a pharmacist. Do not start, stop, or change a dose based on an article or app."),
    ];
}
